/**
 * @name Recon: file read taint into subprocess
 * @description Track file read contents flowing into subprocess command execution
 * @kind problem
 * @problem.severity warning
 * @id py/recon-file-read-subprocess
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module FileReadSubprocessConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(API::CallNode call |
      call = API::moduleImport("builtins").getMember("open").getACall() and
      source = call.getReturn().asSource()
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      (
        call = API::moduleImport("subprocess").getMember(["run", "Popen", "call", "check_call", "check_output", "getoutput", "getstatusoutput"]).getACall() or
        call = API::moduleImport("os").getMember(["system", "popen"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module FileReadSubprocessFlow = TaintTracking::Global<FileReadSubprocessConfig>;

from DataFlow::Node source, DataFlow::Node sink
where FileReadSubprocessFlow::flow(source, sink)
select sink, "Subprocess sink reached by data from file read $@.", source, "source"

/**
 * @name Unsafe deserialization taint
 * @kind problem
 * @problem.severity error
 * @id py/unsafe-deser-taint
 */
import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module DeserConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) { source instanceof RemoteFlowSource }
  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("pickle").getMember(["load", "loads"]).getACall() or
        call = API::moduleImport("marshal").getMember(["load", "loads"]).getACall() or
        call = API::moduleImport("yaml").getMember(["load", "unsafe_load"]).getACall() or
        call = API::moduleImport("shelve").getMember("open").getACall()
      )
      and sink = call.getArg(0)
    )
  }
}

module DeserFlow = TaintTracking::Global<DeserConfig>;

from DataFlow::Node source, DataFlow::Node sink
where DeserFlow::flow(source, sink)
select sink, "Unsafe deserialization from $@.", source, "untrusted input"

